import React, { useContext, useId, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { AlertCircle, CheckCircle, Info } from 'lucide-react';
import { apiClient } from '../../services/network.service';
import { LanguageContext } from '../../context/LanguageContext';
import { useSjoOptions } from '../../components/SjoInvoiceFields';

/**
 * ROSPBU Invoice Processing - create an invoice on its own page (/app/rospbu/invoices/new), with the
 * fields of the "ROSPBU Invoice Edit" layout. Every field is optional; the invoice id is generated by
 * the API. País / BU / ERP come from Settings > Configuration; BU and ERP are enabled once a País is chosen.
 */

// Picklist values (edit here when the business confirms the lists)
export const RETENCION_OPTIONS = ['No aplica', 'Ganancias', 'IVA', 'Ingresos Brutos', 'SUSS'];
export const CURRENCY_OPTIONS = [
  ['ARS', 'ARS - Peso argentino'],
  ['USD', 'USD - Dólar estadounidense'],
  ['EUR', 'EUR - Euro'],
  ['BRL', 'BRL - Real brasileño'],
  ['PYG', 'PYG - Guaraní paraguayo'],
  ['UYU', 'UYU - Peso uruguayo']
];
export const TIPO_OPER_OPTIONS = [
  '1 - B2B (Empresa a empresa)',
  '2 - B2C (Empresa a consumidor)',
  '3 - B2G (Empresa a gobierno)',
  '4 - B2F (Empresa a extranjero)'
];

const emptyForm = () => ({
  countryId: '',
  businessUnitId: '',
  erpSystemId: '',
  retencion: 'No aplica',
  codigoImputacion: '',
  nroAr: '',
  cantidad: '',
  producto: '',
  np: '',
  nroRemito: '',
  filial: '',
  additionalInfo: '',
  numeroDocumento: '',
  generalComment: '',
  amount: '',
  invoiceDate: '',
  centroEmisor: '',
  dueDate: '',
  currency: '',
  poNumber: '',
  instrumentoPago: '',
  timbrado: '',
  bpNumber: '',
  numeroLiquidacion: '',
  branchPlant: '',
  tipoOperacion: ''
});

/** API error as one line: message plus field errors (zod flattenError details). */
const apiErrorText = (err, fallback) => {
  const data = err.response?.data;
  if (!data) return fallback;
  const fields = Object.entries(data.details?.fieldErrors || {}).map(([k, v]) => `${k}: ${[].concat(v).join(', ')}`);
  return [data.message || fallback, ...(data.details?.formErrors || []), ...fields].join(' - ');
};

const optionLabel = (o) => (o.code && o.code !== o.name ? `${o.name} (${o.code})` : o.name);

/** One "label | control" row of the Information section. */
const Row = ({ label, hint, children }) => {
  const id = useId();
  return (
    <div className="rospbu-edit-row">
      <label htmlFor={id}>{label}</label>
      <div className="rospbu-edit-control">
        {React.cloneElement(children, { id })}
        {hint && (
          <span className="rospbu-edit-hint" title={hint} aria-label={hint}>
            <Info size={14} />
          </span>
        )}
      </div>
    </div>
  );
};

const RospbuInvoiceCreate = () => {
  const navigate = useNavigate();
  const { t } = useContext(LanguageContext);
  const options = useSjoOptions(true);
  const [form, setForm] = useState(emptyForm);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [created, setCreated] = useState('');

  const listUrl = '/app/rospbu/invoices';
  const set = (key) => (e) => setForm((f) => ({ ...f, [key]: e.target.value }));
  const codeOfId = (list, id) => list.find((o) => String(o.id) === String(id))?.code ?? '';
  const text = (key, maxLength, props = {}) => (
    <input type="text" className="input-field" value={form[key]} onChange={set(key)} maxLength={maxLength} {...props} />
  );

  const onCountryChange = (e) => {
    const countryId = e.target.value;
    // BU / ERP depend on País: clear them when País is cleared
    setForm((f) => ({ ...f, countryId, ...(countryId ? {} : { businessUnitId: '', erpSystemId: '' }) }));
  };

  const save = async (andNew) => {
    setError('');
    setCreated('');
    setSaving(true);
    const { countryId, businessUnitId, erpSystemId, ...rest } = form;
    const payload = {
      ...rest,
      country: codeOfId(options.countries, countryId),
      businessUnit: codeOfId(options.businessUnits, businessUnitId),
      erp: codeOfId(options.erpSystems, erpSystemId)
    };
    try {
      const response = await apiClient.post('/apps/rospbu/invoices', payload);
      const id = response.data?.data?.id;
      if (andNew) {
        setForm(emptyForm());
        setCreated(id);
        window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
        navigate(`/app/rospbu/invoices/${encodeURIComponent(id)}`, { state: { appName: 'ROSPBU Invoice Processing' } });
      }
    } catch (err) {
      console.error('Failed to create invoice', err);
      setError(apiErrorText(err, t('createInvoiceFailed', 'Failed to create the invoice')));
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } finally {
      setSaving(false);
    }
  };

  const onSubmit = (e) => {
    e.preventDefault();
    save(e.nativeEvent?.submitter?.value === 'new');
  };

  const buttons = (
    <div className="rospbu-edit-buttons">
      <button type="submit" value="save" className="btn btn-primary" disabled={saving}>{t('save', 'Save')}</button>
      <button type="submit" value="new" className="btn btn-outline" disabled={saving}>{t('saveAndNew', 'Save & New')}</button>
      <button type="button" className="btn btn-outline" disabled={saving} onClick={() => navigate(listUrl)}>{t('cancel', 'Cancel')}</button>
    </div>
  );

  const noCountry = !form.countryId;
  const dependsOnPais = t('dependsOnPais', 'Select a País first');

  return (
    <form className="rospbu-edit glass-panel" onSubmit={onSubmit}>
      <div className="rospbu-edit-header">
        <h2>{t('rospbuInvoiceEdit', 'ROSPBU Invoice Edit')}</h2>
        {buttons}
      </div>

      {error && (
        <div className="rospbu-edit-alert rospbu-edit-alert-error" role="alert">
          <AlertCircle size={16} /> {error}
        </div>
      )}
      {created && (
        <div className="rospbu-edit-alert rospbu-edit-alert-success" role="status">
          <CheckCircle size={16} /> {t('invoiceCreatedSuccess', 'Invoice created successfully!')} ({created})
        </div>
      )}

      <h3 className="rospbu-edit-section">{t('information', 'Information')}</h3>
      <div className="rospbu-edit-body">
        <Row label="País">
          <select className="input-field rospbu-w-md" value={form.countryId} onChange={onCountryChange}>
            <option value="">--None--</option>
            {options.countries.map((o) => <option key={o.id} value={o.id}>{optionLabel(o)}</option>)}
          </select>
        </Row>
        <Row label="BU" hint={dependsOnPais}>
          <select className="input-field rospbu-w-sm" value={form.businessUnitId} onChange={set('businessUnitId')} disabled={noCountry}>
            <option value="">--None--</option>
            {options.businessUnits.map((o) => <option key={o.id} value={o.id}>{optionLabel(o)}</option>)}
          </select>
        </Row>
        <Row label="ERP" hint={dependsOnPais}>
          <select className="input-field rospbu-w-sm" value={form.erpSystemId} onChange={set('erpSystemId')} disabled={noCountry}>
            <option value="">--None--</option>
            {options.erpSystems.map((o) => <option key={o.id} value={o.id}>{optionLabel(o)}</option>)}
          </select>
        </Row>
        <Row label="Retención">
          <select className="input-field rospbu-w-sm" value={form.retencion} onChange={set('retencion')}>
            {RETENCION_OPTIONS.map((o) => <option key={o} value={o}>{o}</option>)}
          </select>
        </Row>
        <Row label="Código Imputación">{text('codigoImputacion', 255)}</Row>
        <Row label="Nro AR">{text('nroAr', 50)}</Row>
        <Row label="Cantidad">
          <input type="number" className="input-field" value={form.cantidad} onChange={set('cantidad')} min="0" step="any" />
        </Row>
        <Row label="Producto">{text('producto', 255)}</Row>
        <Row label="NP">
          <textarea className="input-field rospbu-w-lg" rows={4} value={form.np} onChange={set('np')} maxLength={4000} />
        </Row>
        <Row label="Nº de remito">{text('nroRemito', 50)}</Row>
        <Row label="FILIAL">{text('filial', 100)}</Row>
        <Row label="Adicional Info">{text('additionalInfo', 1000)}</Row>
        <Row label="Número de Documento">{text('numeroDocumento', 50)}</Row>
        <Row label="General Comment">{text('generalComment', 1000)}</Row>
        <Row label="Total de la FC">
          <input type="number" className="input-field" value={form.amount} onChange={set('amount')} min="0" step="0.01" />
        </Row>
        <Row label="Fecha de Fc">
          <input type="date" className="input-field" value={form.invoiceDate} onChange={set('invoiceDate')} />
        </Row>
        <Row label="Centro Emisor">{text('centroEmisor', 20)}</Row>
        <Row label="Fecha de Vencimiento">
          <input type="date" className="input-field" value={form.dueDate} onChange={set('dueDate')} min={form.invoiceDate || undefined} />
        </Row>
        <Row label="Moneda de la Fc">
          <select className="input-field rospbu-w-sm" value={form.currency} onChange={set('currency')}>
            <option value="">--None--</option>
            {CURRENCY_OPTIONS.map(([code, label]) => <option key={code} value={code}>{label}</option>)}
          </select>
        </Row>
        <Row label="Nº de OC">{text('poNumber', 50)}</Row>
        <Row label="Instrumento de Pago">{text('instrumentoPago', 100)}</Row>
        <Row label="Timbrado">{text('timbrado', 50)}</Row>
        <Row label="BP Number">{text('bpNumber', 50)}</Row>
        <Row label="Número de Liquidación">{text('numeroLiquidacion', 50)}</Row>
        <Row label="Branch Plant">{text('branchPlant', 100)}</Row>
        <Row label="G_TIPO_OPER">
          <select className="input-field rospbu-w-xl" value={form.tipoOperacion} onChange={set('tipoOperacion')}>
            <option value="">--None--</option>
            {TIPO_OPER_OPTIONS.map((o) => <option key={o} value={o}>{o}</option>)}
          </select>
        </Row>
      </div>

      <div className="rospbu-edit-footer">{buttons}</div>
    </form>
  );
};

export default RospbuInvoiceCreate;
